type Key = string | number;

export function memoize<K extends Key, V>(fn: (key: K) => V): (key: K) => V {
  const cache = new Map<K, V>();
  return (key: K): V => {
    if (!cache.has(key)) cache.set(key, fn(key));
    return cache.get(key) as V;      // has() checked the miss, so this is the stored value
  };
}

export const cost = memoize((sku: string) => computeCost(sku));

