const derived = new WeakMap<object, Layout>();

export function layoutOf(node: object): Layout {
  let hit = derived.get(node);
  if (hit === undefined) derived.set(node, (hit = computeLayout(node)));
  return hit;                        // entry is collectable with the node
}

import { useMemo } from 'react';

function TodoList({ todos, tab }: Props) {
  const visible = useMemo(() => filter(todos, tab), [todos, tab]);   // discarded freely
  return <List items={visible} />;
}
